mapper.select:
SELECT FROM assets a LEFT JOIN asset_tags link ON link.asset_id = a.id WHERE a.type = #{type}
AND (instr(lower(a.name), lower(#{query})) > 0 OR instr(lower(a.description), lower(#{query})) > 0 OR (a.type = 'snippet' AND instr(lower(a.content), lower(#{query})) > 0) OR EXISTS ( SELECT 1 FROM asset_tags atag JOIN tags t ON t.id = atag.tag_id WHERE atag.asset_id = a.id AND instr(lower(t.name), lower(#{query})) > 0 ))
ORDER BY a.updated_at DESC, a.name, a.id, link.tag_id

SELECT EXISTS (
    SELECT 1 FROM assets WHERE type = #{type} AND name = #{name}

        AND id != #{excludeAssetId}
        AND EXISTS (SELECT 1 FROM assets WHERE id = #{excludeAssetId} AND type = #{type})

)

mapper.update:
UPDATE assets SET
    name = COALESCE(#{asset.name}, name),
    description = COALESCE(#{asset.description}, description),
    content = COALESCE(#{asset.content}, content),
    enabled = COALESCE(#{asset.enabled}, enabled),
    updated_at = CASE WHEN #{tagsChanged}
        OR name != #{asset.name}
        OR description != #{asset.description}
        OR content != #{asset.content}
        OR enabled != #{asset.enabled}
        THEN MAX(updated_at + 1, #{now}) ELSE updated_at END
WHERE id = #{asset.id} AND type = #{asset.type.value}
